const W=48,H=22,ground=0;
function xy(x,y,z=0){return [368+(x-y)*W,93+(x+y)*H-z]}
function polygon(points,ink){ctx.fillStyle=ink;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill()}
function line(points,ink,width=1){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.strokeStyle=ink;ctx.lineWidth=width;ctx.stroke()}
function rect(x,y,w,h,ink){ctx.fillStyle=ink;ctx.fillRect(x,y,w,h)}
function text(x,y,s,ink,size=13){ctx.font="bold "+size+"px Consolas,monospace";ctx.fillStyle=ink;ctx.fillText(s,x,y)}
function plate(x,y,w,d,z,ink){polygon([xy(x,y,z),xy(x+w,y,z),xy(x+w,y+d,z),xy(x,y+d,z)],ink)}
function solid(x,y,w,d,z,height,top,front,side){
 const corner=(a,b,k)=>xy(x+a,y+b,z+k);
 polygon([corner(0,d,height),corner(w,d,height),corner(w,d,0),corner(0,d,0)],front);
 polygon([corner(w,0,height),corner(w,d,height),corner(w,d,0),corner(w,0,0)],side);
 plate(x,y,w,d,z+height,top)
}
function wall(x,y,z,side,paint){const [sx,sy]=xy(x,y,z);ctx.save();ctx.transform(side?-1:1,H/W,0,1,sx,sy);paint();ctx.restore()}
