 solid(x-.035,y-.035,w+.07,d+.07,top-5,5,"#a19b97","#aea19c","#787985");
 plate(x,y,w,d,top,kind?"#767580":"#718287");
 for(let i=0;i<w;i++)for(let j=0;j<d;j++){
  plate(x+i+.025,y+j+.025,.95,.95,top+.15,(i+j)%2?(kind?"#4d444f":"#637579"):(kind?"#4c434e":"#5f7275"));
  plate(x+i+.1,y+j+.1,.035,.04,top+1,"#b5b3ad");plate(x+i+.88,y+j+.88,.035,.04,top+1,"#595c69")
 }
