  buy.disabled=owned?player.slot===i:player.credits<g.price;
  buy.onclick=()=>{if(mode!=="shop")return;if(!player.owned.includes(i)){if(player.credits<g.price)return;player.credits-=g.price;player.owned.push(i);pendingSale=true}selectGun(i);renderCatalog()};
