function updateLook(dt){
 const p=player;let dx,dy;
 if(mouse.seen){
  const [headX,headY]=xy(p.x,p.y,59);
  dx=(mouse.x-480)/camera.zoom+camera.x-headX;dy=(mouse.y-270)/camera.zoom+camera.y-headY;
  if(Math.hypot(dx,dy)<2)return;
 }else [dx,dy]=gunVector();
 const target=Math.atan2(dx,-dy),difference=Math.atan2(Math.sin(target-p.lookAngle),Math.cos(target-p.lookAngle));
 p.lookAngle+=clamp(difference,-dt*14,dt*14);
 p.lookIndex=(Math.round(p.lookAngle*8/Math.PI)%16+16)%16
}
let previous=null;function tick(t){const dt=previous===null?0:Math.min(.035,(t-previous)/1000);previous=t;step(dt);const [px,py]=xy(player.x,player.y,12),k=1-Math.exp(-dt*5.4);
 camera.x+=(px-camera.x)*k;camera.y+=(py-camera.y)*k;updateLook(dt);draw(t);requestAnimationFrame(tick)}
function keyDown(k){if(mode==="shop")return;awaken();if(k==="KeyF")return openShop();if(k==="Cycle")return selectGun(player.owned[(player.owned.indexOf(player.slot)+1)%player.owned.length]);if(k.startsWith("Digit"))return selectGun(Number(k.slice(-1))-1);keys.add(k);if(k==="KeyE")pulse();if(k.startsWith("Shift"))dash()}
document.addEventListener("keydown",e=>{if(mode==="shop")return;if(!["KeyF","Digit4","Digit5","Digit6","Digit7","Digit8","Digit9","Digit1","Digit2","Digit3","KeyW","KeyA","KeyS","KeyD","KeyE","ShiftLeft","ShiftRight","Space","ArrowUp","ArrowDown","ArrowLeft","ArrowRight"].includes(e.code)||e.target.tagName==="BUTTON"&&e.code==="Space")return;e.preventDefault();if(!e.repeat)keyDown(e.code)});
document.addEventListener("keyup",e=>keys.delete(e.code));
function aim(e){mouse.seen=true;const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)*canvas.width/r.width;mouse.y=(e.clientY-r.top)*canvas.height/r.height}
canvas.onpointerdown=e=>{if(e.button!==0)return;aim(e);awaken();mouse.down=true;canvas.setPointerCapture(e.pointerId)};
canvas.onpointermove=aim;canvas.onpointerup=canvas.onpointercancel=()=>mouse.down=false;
window.addEventListener("blur",()=>{keys.clear();mouse.down=false});
document.querySelectorAll("[data-k]").forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keyDown(b.dataset.k)};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.k)});
